"use client"

import { useState, useMemo } from "react"
import { SlidingSidebar } from "@/components/sliding-sidebar"
import { SearchFilters } from "@/components/search-filters"
import { DateCalendar } from "@/components/date-calendar"
import { EventsCarousel } from "@/components/events-carousel"
import { EventsGrid } from "@/components/events-grid"
import { EventModal } from "@/components/event-modal"
import { mockEvents, type Event } from "@/lib/events-data"
import { Sparkles } from "lucide-react"

export default function HomePage() {
  const [searchValue, setSearchValue] = useState("")
  const [selectedCategory, setSelectedCategory] = useState("Все категории")
  const [priceRange, setPriceRange] = useState([0, 5000])
  const [attendeesFilter, setAttendeesFilter] = useState("all")
  const [selectedDate, setSelectedDate] = useState<string | null>(null)
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null)

  // Get all event dates for calendar
  const eventDates = useMemo(() => {
    return [...new Set(mockEvents.map((event) => event.date))]
  }, [])

  const filteredEvents = useMemo(() => {
    return mockEvents.filter((event) => {
      // Date filter
      if (selectedDate && event.date !== selectedDate) {
        return false
      }

      // Search filter
      if (searchValue) {
        const searchLower = searchValue.toLowerCase()
        const matchesSearch =
          event.title.toLowerCase().includes(searchLower) ||
          event.description.toLowerCase().includes(searchLower) ||
          event.category.toLowerCase().includes(searchLower) ||
          event.tags.some((tag) => tag.toLowerCase().includes(searchLower))
        if (!matchesSearch) return false
      }

      // Category filter
      if (selectedCategory !== "Все категории" && event.category !== selectedCategory) {
        return false
      }

      // Price filter
      if (!event.isFree && (event.price < priceRange[0] || event.price > priceRange[1])) {
        return false
      }

      // Attendees filter
      if (attendeesFilter !== "all") {
        if (attendeesFilter === "small" && event.maxAttendees > 50) return false
        if (attendeesFilter === "medium" && (event.maxAttendees < 50 || event.maxAttendees > 500)) return false
        if (attendeesFilter === "large" && event.maxAttendees < 500) return false
      }

      return true
    })
  }, [searchValue, selectedCategory, priceRange, attendeesFilter, selectedDate])

  // Get featured events for carousel (top 6 by attendance)
  const featuredEvents = useMemo(() => {
    return [...mockEvents].sort((a, b) => b.currentAttendees - a.currentAttendees).slice(0, 10)
  }, [])

  return (
    <div className="min-h-screen bg-background">
      <SlidingSidebar />

      {/* Main Content */}
      <main className="pl-4 lg:pl-8">
        {/* Hero Section */}
        <section className="relative py-16 px-4 lg:px-8">
          <div className="max-w-7xl mx-auto text-center space-y-6">
            <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-card border border-border">
              <Sparkles className="w-4 h-4 text-primary" />
              <span className="text-sm text-muted-foreground">Маркетплейс мероприятий вашего города</span>
            </div>

            <h1 className="text-4xl md:text-6xl font-bold text-foreground tracking-tight text-balance">
              Найдите идеальное
              <br />
              <span className="text-muted-foreground">мероприятие для себя</span>
            </h1>

            <p className="text-lg text-muted-foreground max-w-2xl mx-auto text-pretty">
              Настольные игры, покер, шахматы, концерты и спектакли. Все мероприятия города в одном месте.
            </p>

            {/* Date Calendar */}
            <div className="pt-6">
              <DateCalendar
                selectedDate={selectedDate}
                onDateSelect={setSelectedDate}
                eventDates={eventDates}
              />
            </div>

            {/* Search & Filters */}
            <div className="pt-4">
              <SearchFilters
                searchValue={searchValue}
                selectedCategory={selectedCategory}
                priceRange={priceRange}
                attendeesFilter={attendeesFilter}
                onSearchChange={setSearchValue}
                onCategoryChange={setSelectedCategory}
                onPriceChange={setPriceRange}
                onAttendeesChange={setAttendeesFilter}
              />
            </div>
          </div>
        </section>

        {/* Featured Carousel */}
        <section className="py-8 px-4 lg:px-8">
          <div className="max-w-7xl mx-auto">
            <EventsCarousel events={featuredEvents} onEventClick={setSelectedEvent} />
          </div>
        </section>

        {/* Events Grid */}
        <section className="py-8 px-4 lg:px-8 pb-20">
          <div className="max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-6">
              <div>
                <h2 className="text-2xl font-bold text-foreground">Все мероприятия</h2>
                <p className="text-muted-foreground mt-1">Найдено {filteredEvents.length} мероприятий</p>
              </div>
            </div>

            <EventsGrid events={filteredEvents} onEventClick={setSelectedEvent} />
          </div>
        </section>
      </main>

      {/* Event Modal */}
      <EventModal event={selectedEvent} onClose={() => setSelectedEvent(null)} />
    </div>
  )
}
