"use client"

import { useState } from "react"
import { Search, SlidersHorizontal, X } from "lucide-react"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Slider } from "@/components/ui/slider"
import { Badge } from "@/components/ui/badge"
import { categories } from "@/lib/events-data"

interface SearchFiltersProps {
  onSearchChange: (value: string) => void
  onCategoryChange: (value: string) => void
  onPriceChange: (value: number[]) => void
  onAttendeesChange: (value: string) => void
  searchValue: string
  selectedCategory: string
  priceRange: number[]
  attendeesFilter: string
}

export function SearchFilters({
  onSearchChange,
  onCategoryChange,
  onPriceChange,
  onAttendeesChange,
  searchValue,
  selectedCategory,
  priceRange,
  attendeesFilter,
}: SearchFiltersProps) {
  const [showFilters, setShowFilters] = useState(false)

  const hasActiveFilters =
    selectedCategory !== "Все категории" || priceRange[0] > 0 || priceRange[1] < 5000 || attendeesFilter !== "all"

  const clearFilters = () => {
    onCategoryChange("Все категории")
    onPriceChange([0, 5000])
    onAttendeesChange("all")
    onSearchChange("")
  }

  return (
    <div className="w-full max-w-5xl mx-auto space-y-4">
      {/* Main Search Bar */}
      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
        <Input
          type="text"
          placeholder="Поиск мероприятий..."
          value={searchValue}
          onChange={(e) => onSearchChange(e.target.value)}
          className="w-full h-14 pl-12 pr-4 text-lg bg-card border-border rounded-xl focus:ring-2 focus:ring-primary/20"
        />
        <Button
          variant="ghost"
          size="icon"
          className="absolute right-2 top-1/2 -translate-y-1/2"
          onClick={() => setShowFilters(!showFilters)}
        >
          <SlidersHorizontal className="w-5 h-5" />
        </Button>
      </div>

      {/* Active Filters Badges */}
      {hasActiveFilters && (
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-sm text-muted-foreground">Активные фильтры:</span>
          {selectedCategory !== "Все категории" && (
            <Badge variant="secondary" className="gap-1">
              {selectedCategory}
              <X className="w-3 h-3 cursor-pointer" onClick={() => onCategoryChange("Все категории")} />
            </Badge>
          )}
          {(priceRange[0] > 0 || priceRange[1] < 5000) && (
            <Badge variant="secondary" className="gap-1">
              {priceRange[0]} - {priceRange[1]} ₽
              <X className="w-3 h-3 cursor-pointer" onClick={() => onPriceChange([0, 5000])} />
            </Badge>
          )}
          {attendeesFilter !== "all" && (
            <Badge variant="secondary" className="gap-1">
              {attendeesFilter === "small"
                ? "До 50 человек"
                : attendeesFilter === "medium"
                  ? "50-500 человек"
                  : "Более 500 человек"}
              <X className="w-3 h-3 cursor-pointer" onClick={() => onAttendeesChange("all")} />
            </Badge>
          )}
          <Button variant="ghost" size="sm" onClick={clearFilters} className="text-muted-foreground">
            Сбросить все
          </Button>
        </div>
      )}

      {/* Expanded Filters */}
      {showFilters && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 p-6 bg-card rounded-xl border border-border animate-in slide-in-from-top-2">
          {/* Category */}
          <div className="flex flex-col items-center space-y-2">
            <label className="text-sm font-medium text-foreground text-center">Категория</label>
            <Select value={selectedCategory} onValueChange={onCategoryChange}>
              <SelectTrigger className="bg-input border-border w-full max-w-[200px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {categories.map((cat) => (
                  <SelectItem key={cat} value={cat}>
                    {cat}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Price Range */}
          <div className="flex flex-col items-center space-y-2">
            <label className="text-sm font-medium text-foreground text-center">
              Цена: {priceRange[0]} - {priceRange[1]} ₽
            </label>
            <div className="h-10 flex items-center w-full max-w-[280px]">
              <Slider value={priceRange} onValueChange={onPriceChange} min={0} max={5000} step={100} className="w-full" />
            </div>
          </div>

          {/* Attendees */}
          <div className="flex flex-col items-center space-y-2">
            <label className="text-sm font-medium text-foreground text-center">Количество участников</label>
            <Select value={attendeesFilter} onValueChange={onAttendeesChange}>
              <SelectTrigger className="bg-input border-border w-full max-w-[200px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Любое количество</SelectItem>
                <SelectItem value="small">До 50 человек</SelectItem>
                <SelectItem value="medium">50-500 человек</SelectItem>
                <SelectItem value="large">Более 500 человек</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      )}
    </div>
  )
}
